#[using="Type"] Theorem art_allocate_post_small : forall r8 (M8 rom : word -> option byte) (raw : word) (sp n qn m8 rs qr rz qz c qs ch ab t tp loff key tsd ctx id sab b1 mc mb mr mbs f120 f112 f104 f96 f88 f80 f72 f64 f56 f48 f40 f32 f24 : Z),
  f120 = U raw ->
  ret_ok raw ->
  getr r8 2 = Z_to_bv 64 (sp - 128) -> getr r8 4 = Z_to_bv 64 tp -> getr r8 8 = Z_to_bv 64 1 -> getr r8 9 = Z_to_bv 64 n -> getr r8 10 = Z_to_bv 64 id ->
  getr r8 18 = Z_to_bv 64 ab -> getr r8 19 = Z_to_bv 64 (rs + rz) -> getr r8 20 = Z_to_bv 64 (ab + rz) -> getr r8 21 = Z_to_bv 64 (ab + rz - 16) -> getr r8 24 = Z_to_bv 64 0 ->
  (* [comment removed for export] *)
  1 <= n < 8 -> n = 8 * qn + m8 -> 0 <= m8 <= 7 -> rs = 8 * qr -> n <= rs <= n + 7 -> rz = 16 * qz -> 16 <= rz <= 2048 -> rs + rz <= 65536 ->
  c = AsanTab.class_id (rs + rz) -> 0 <= qs -> 0 <= ch < 2 ^ 32 -> ab = 16 * qs + c * 2 ^ 32 + ch * 16 ->
  (* [comment removed for export] *)
  0x10007fff8000 + 4096 <= sp -> sp + 2144 <= 2 ^ 47 ->
  4096 <= t -> t + 4096 < 2 ^ 47 -> (t + 4096 <= 0x10000 \/ 0x698000 <= t) -> apart t 4096 (sp - 1952) 6048 -> apart t 4096 0x7fff8000 0x100000000000 ->
  apart ctx 4096 (sp - 1952) 6048 -> (ctx + 4096 <= 0x10000 \/ 0x698000 <= ctx) -> apart t 4096 ctx 4096 -> apart ctx 4096 0x7fff8000 0x100000000000 ->
  0 <= loff -> 0x10100 <= tp -> 0x10000 <= tp + loff -> tp + loff + 4 <= 0x698000 -> 0x10000 <= tsd -> tsd + 1024 <= 0x698000 ->
  0x10007fff8000 <= ab -> ab + 65536 < 2 ^ 47 -> apart ab 65536 (sp - 1952) 6048 -> apart ab 65536 t 4096 -> apart ab 65536 ctx 4096 ->
  0 <= id < 2 ^ 32 -> 1 <= sab < 256 -> 0 <= b1 < 256 -> 0 <= mc < 2 ^ 64 -> 0 <= mb < 2 ^ 64 -> 0 <= mr < 2 ^ 64 -> 0 <= mbs < 2 ^ 64 ->
  0 <= f120 < 2 ^ 64 -> 0 <= f112 < 2 ^ 64 -> 0 <= f104 < 2 ^ 64 -> 0 <= f96 < 2 ^ 64 -> 0 <= f88 < 2 ^ 64 -> 0 <= f80 < 2 ^ 64 -> 0 <= f72 < 2 ^ 64 ->
  0 <= f64 < 2 ^ 64 -> 0 <= f56 < 2 ^ 64 -> 0 <= f48 < 2 ^ 64 -> 0 <= f40 < 2 ^ 64 -> 0 <= f32 < 2 ^ 64 -> 0 <= f24 < 2 ^ 64 ->
  (* [comment removed for export] *)
  wrA M8 (sp - 1952) 1952 -> wrA M8 ab (rs + rz) -> wrA M8 (0x7fff8000 + ab / 8) 8192 -> wrA M8 t 4096 ->
  art_layout M8 -> art_tsd M8 tp key tsd ctx t ->
  cellA M8 (0x7fff8000 + ab / 8) 1 sab -> cellA M8 (0x13f1f8 + 85) 1 1 -> cellA M8 (0x13f1f8 + 44) 4 4096 -> cellA M8 (0x13f1f8 + 52) 4 190 ->
  cellA M8 0x139e18 8 loff -> cellA M8 (tp + loff) 4 0 -> cellA M8 0x1d34c0 8 0 -> cellA M8 0x10370 8 0xcc6e96b9cc6e96b9 ->
  cellA M8 (t + 2800) 8 mc -> cellA M8 (t + 2800 + 8) 8 mb -> cellA M8 (t + 2800 + 16) 8 mr -> cellA M8 (t + 2800 + 112 + 8 * c) 8 mbs ->
  cellA M8 (ab + rz - 15) 1 b1 -> cellA M8 (ab + rz - 12) 4 n -> cellA M8 (ab + rz - 14) 2 0 ->
  cellA M8 (sp - 128 + 8) 8 1 ->
  cellA M8 (sp - 128 + 120) 8 f120 -> cellA M8 (sp - 128 + 112) 8 f112 -> cellA M8 (sp - 128 + 104) 8 f104 -> cellA M8 (sp - 128 + 96) 8 f96 -> cellA M8 (sp - 128 + 88) 8 f88 -> cellA M8 (sp - 128 + 80) 8 f80 -> cellA M8 (sp - 128 + 72) 8 f72 -> cellA M8 (sp - 128 + 64) 8 f64 -> cellA M8 (sp - 128 + 56) 8 f56 -> cellA M8 (sp - 128 + 48) 8 f48 -> cellA M8 (sp - 128 + 40) 8 f40 -> cellA M8 (sp - 128 + 32) 8 f32 -> cellA M8 (sp - 128 + 24) 8 f24 ->
  exists regs' M',
    msteps ASEGS (mkst r8 (0x53178 : word) M8 rom) (mkst regs' raw M' rom)
    /\ getr regs' 10 = Z_to_bv 64 (ab + rz) /\ getr regs' 2 = Z_to_bv 64 sp /\ getr regs' 1 = raw
    /\ getr regs' 8 = Z_to_bv 64 f112 /\ getr regs' 9 = Z_to_bv 64 f104 /\ getr regs' 18 = Z_to_bv 64 f96 /\ getr regs' 19 = Z_to_bv 64 f88
    /\ getr regs' 20 = Z_to_bv 64 f80 /\ getr regs' 21 = Z_to_bv 64 f72 /\ getr regs' 22 = Z_to_bv 64 f64 /\ getr regs' 23 = Z_to_bv 64 f56
    /\ getr regs' 24 = Z_to_bv 64 f48 /\ getr regs' 25 = Z_to_bv 64 f40 /\ getr regs' 26 = Z_to_bv 64 f32 /\ getr regs' 27 = Z_to_bv 64 f24
    /\ mem_grows M8 M'
    /\ (forall x : word, ~ art_post_writtenG sp t c ab rz n rs (U x) -> M' x = M8 x)
    /\ cellA M' (ab + rz - 16) 1 2 /\ cellA M' (ab + rz - 12) 4 n /\ cellA M' (ab + rz - 15) 1 (Z.land b1 243) /\ cellA M' (ab + rz - 14) 2 0
    /\ (forall j, 0 <= j < qn -> cellA M' (2147450880 + ab / 8 + 2 * qz + j) 1 0) /\ (m8 <> 0 -> cellA M' (2147450880 + ab / 8 + 2 * qz + qn) 1 m8)
    /\ getr regs' 3 = getr r8 3 /\ getr regs' 4 = getr r8 4
    /\ (rz <> 16 -> cellA M' ab 8 0xcc6e96b9cc6e96b9 /\ cellA M' (ab + 8) 8 (ab + rz - 16)).
Proof.
